## Agent SDK Interface

### ACP-Compatible Agent

Agents that want to receive ACP-tunneled messages must:
1. Advertise ACP capability during registration
2. Handle the ACP envelope format

```typescript
// Register with ACP capability
const mapAgent = await AgentConnection.connect('ws://localhost:8080', {
  name: 'CodingAgent',
  capabilities: {
    protocols: ['acp'],
    acp: { version: '2024-10-07', features: ['loadSession', 'modes'] }
  }
});

// Handle incoming messages
mapAgent.onMessage(async (message) => {
  if (message.metadata?.protocol === 'acp') {
    await handleACPMessage(message);
  }
});
```

### Helper: ACPAgentAdapter

To simplify agent implementation, use the adapter:

```typescript
import { ACPAgentAdapter } from '@anthropic/map-sdk';

const adapter = new ACPAgentAdapter(mapAgent, {
  initialize: async (params, ctx) => {
    return {
      protocolVersion: '2024-10-07',
      agentInfo: { name: 'CodingAgent', version: '1.0.0' },
      capabilities: { loadSession: true }
    };
  },

  newSession: async (params, ctx) => {
    const sessionId = generateSessionId();
    return { sessionId };
  },

  prompt: async (params, ctx) => {
    // Stream updates to client
    await adapter.sendSessionUpdate(ctx.streamId, {
      sessionId: params.sessionId,
      update: { type: 'message_start', message: {...} }
    });

    // Request permission if needed
    const permission = await adapter.requestPermission(ctx.streamId, {
      sessionId: params.sessionId,
      toolCall: { id: '1', name: 'bash', input: { command: 'npm test' } }
    });

    if (permission.outcome === 'allowed') {
      // Option A: Use client's terminal
      const terminal = await adapter.createTerminal(ctx.streamId, {
        sessionId: params.sessionId,
        command: 'npm test'
      });

      // Option B: Execute server-side (implementation choice)
      // const result = await exec('npm test');
    }

    return { stopReason: 'end_turn' };
  },

  cancel: async (params, ctx) => {
    // Abort any in-progress work
  }
});
```

### ACPAgentAdapter Interface

```typescript
class ACPAgentAdapter {
  constructor(mapAgent: AgentConnection, handler: ACPAgentHandler);

  /** Send session update notification to client */
  sendSessionUpdate(streamId: string, update: ACP.SessionNotification): Promise<void>;

  /** Request permission from client (blocks until user responds) */
  requestPermission(streamId: string, request: ACP.RequestPermissionRequest): Promise<ACP.RequestPermissionResponse>;

  /** Read file from client filesystem */
  readTextFile(streamId: string, request: ACP.ReadTextFileRequest): Promise<ACP.ReadTextFileResponse>;

  /** Write file to client filesystem */
  writeTextFile(streamId: string, request: ACP.WriteTextFileRequest): Promise<ACP.WriteTextFileResponse>;

  /** Create terminal on client */
  createTerminal(streamId: string, request: ACP.CreateTerminalRequest): Promise<ACP.CreateTerminalResponse>;

  /** Get terminal output from client */
  terminalOutput(streamId: string, request: ACP.TerminalOutputRequest): Promise<ACP.TerminalOutputResponse>;

  /** Release terminal on client */
  releaseTerminal(streamId: string, request: ACP.ReleaseTerminalRequest): Promise<ACP.ReleaseTerminalResponse>;

  /** Wait for terminal exit on client */
  waitForTerminalExit(streamId: string, request: ACP.WaitForTerminalExitRequest): Promise<ACP.WaitForTerminalExitResponse>;

  /** Kill terminal command on client */
  killTerminal(streamId: string, request: ACP.KillTerminalCommandRequest): Promise<ACP.KillTerminalCommandResponse>;
}

interface ACPAgentHandler {
  initialize(params: ACP.InitializeRequest, ctx: ACPContext): Promise<ACP.InitializeResponse>;
  authenticate?(params: ACP.AuthenticateRequest, ctx: ACPContext): Promise<ACP.AuthenticateResponse>;
  newSession(params: ACP.NewSessionRequest, ctx: ACPContext): Promise<ACP.NewSessionResponse>;
  loadSession?(params: ACP.LoadSessionRequest, ctx: ACPContext): Promise<ACP.LoadSessionResponse>;
  setSessionMode?(params: ACP.SetSessionModeRequest, ctx: ACPContext): Promise<ACP.SetSessionModeResponse>;
  prompt(params: ACP.PromptRequest, ctx: ACPContext): Promise<ACP.PromptResponse>;
  cancel(params: ACP.CancelNotification, ctx: ACPContext): Promise<void>;
}

interface ACPContext {
  streamId: string;
  sessionId: string | null;
  clientParticipantId: string;
}
```

