## Extension Registration (Server-Side)

Servers register extensions at startup or runtime.

```typescript
interface ExtensionRegistry {
  // Register an extension with the server
  register(manifest: ExtensionManifest, handler: ExtensionHandler): void;

  // Check if an extension is available
  isAvailable(extensionId: string): boolean;

  // Get extension manifest
  getManifest(extensionId: string): ExtensionManifest | undefined;

  // List all registered extensions
  listExtensions(): ExtensionManifest[];

  // Check if a method belongs to an extension
  getExtensionForMethod(method: string): string | undefined;
}

interface ExtensionHandler {
  // Handle extension method calls
  handleRequest(method: string, params: unknown, context: RequestContext): Promise<unknown>;

  // Handle extension notifications (optional)
  handleNotification?(method: string, params: unknown, context: RequestContext): void;

  // Check if participant can use this extension
  checkAccess?(participant: Participant): ExtensionAccessResult;
}

interface ExtensionAccessResult {
  allowed: boolean;
  capabilities?: string[];           // Granted capabilities within extension
  reason?: string;                   // If not allowed, why
}
```

