## SDK Patterns for Extensions

### Extension Client Pattern

Each extension provides a typed client that wraps the base connection:

```typescript
// Example: Conversation extension client
class ConversationClient {
  private connection: ClientConnection;

  constructor(connection: ClientConnection) {
    // Verify extension is available
    const ext = connection.getExtension('conversations');
    if (!ext?.enabled) {
      throw new Error('Conversation extension not available');
    }
    this.connection = connection;
  }

  async create(params: ConvCreateParams): Promise<Conversation> {
    const result = await this.connection.request('conv/create', params);
    return result.conversation;
  }

  async join(conversationId: string): Promise<JoinResult> {
    return this.connection.request('conv/join', { conversationId });
  }

  // ... other methods
}

// Usage
const client = new ClientConnection(stream);
await client.connect({ capabilities: { extensions: { supported: [{ id: 'conversations', version: '1.0' }] } } });

if (client.hasExtension('conversations')) {
  const conv = new ConversationClient(client);
  const conversation = await conv.create({ type: 'multi-agent' });
}
```

### Extension Server Handler Pattern

```typescript
// Server-side extension handler
const conversationHandler: ExtensionHandler = {
  async handleRequest(method, params, context) {
    switch (method) {
      case 'conv/create':
        return createConversation(params, context);
      case 'conv/join':
        return joinConversation(params, context);
      case 'conv/turn':
        return addTurn(params, context);
      // ...
    }
  },

  checkAccess(participant) {
    // Check if participant has required capabilities
    if (!participant.capabilities?.messaging?.canSend) {
      return { allowed: false, reason: 'Requires messaging.canSend' };
    }
    return { allowed: true, capabilities: ['conversations.canCreate', 'conversations.canJoin'] };
  }
};

// Register with server
server.extensions.register(CONVERSATION_MANIFEST, conversationHandler);
```

