## Core Types

### Identifiers

```typescript
// Branded ID types for type safety
type ConversationId = string;   // Format: 'conv-{ulid}'
type TurnId = string;           // Format: 'turn-{ulid}'
type ThreadId = string;         // Format: 'thread-{ulid}'
```

### Conversation

```typescript
type ConversationType = 
  | 'user-session'    // User interacting with agent(s)
  | 'agent-task'      // Agent working autonomously (trajectory)
  | 'multi-agent'     // Agent-to-agent coordination
  | 'mixed';          // Any combination

type ConversationStatus = 
  | 'active'          // Ongoing conversation
  | 'paused'          // Temporarily suspended
  | 'completed'       // Successfully finished
  | 'failed'          // Ended due to error
  | 'archived';       // Closed and archived

interface Conversation {
  id: ConversationId;
  type: ConversationType;
  status: ConversationStatus;

  // Human-readable subject/title
  subject?: string;

  // Current participants (use conv/get with include.participants for full list)
  participantCount: number;

  // Nesting - conversations can spawn child conversations
  parentConversationId?: ConversationId;
  parentTurnId?: TurnId;              // Which turn spawned this conversation

  // Timestamps
  createdAt: Timestamp;
  updatedAt: Timestamp;
  closedAt?: Timestamp;

  // Who started this conversation
  createdBy: ParticipantId;

  // Extension metadata
  metadata?: Record<string, unknown>;
}
```

### Conversation Participant

```typescript
type ParticipantRole = 
  | 'initiator'       // Started the conversation
  | 'assistant'       // Agent helping the initiator
  | 'worker'          // Agent performing sub-tasks
  | 'observer'        // Can see but not participate
  | 'moderator';      // Can manage participants

interface ConversationParticipant {
  id: ParticipantId;
  type: 'user' | 'agent' | 'system';

  // Role in this conversation
  role: ParticipantRole;

  // Participation timeline
  joinedAt: Timestamp;
  leftAt?: Timestamp;

  // What this participant can do
  permissions: ConversationPermissions;

  // Agent-specific info (if type === 'agent')
  agentInfo?: {
    agentId: AgentId;
    name?: string;
    role?: string;               // MAP agent role
  };
}

interface ConversationPermissions {
  // Can add turns to the conversation
  canSend: boolean;

  // Can see turns (but not necessarily participate)
  canObserve: boolean;

  // Can invite new participants
  canInvite: boolean;

  // Can remove participants
  canRemove: boolean;

  // Can create threads
  canCreateThreads: boolean;

  // How much history can this participant see
  historyAccess: 'none' | 'from-join' | 'full';

  // Can see internal turns (agent thoughts, etc.)
  canSeeInternal: boolean;
}
```

### Thread

```typescript
interface Thread {
  id: ThreadId;
  conversationId: ConversationId;

  // Threads can nest
  parentThreadId?: ThreadId;

  // What this thread is about
  subject?: string;

  // The turn that started this thread
  rootTurnId: TurnId;

  // Stats
  turnCount: number;
  participantCount: number;

  // Timestamps
  createdAt: Timestamp;
  updatedAt: Timestamp;

  createdBy: ParticipantId;
}
```

### Turn

A turn is the atomic unit of conversation - any interaction from any participant.

```typescript
interface Turn {
  id: TurnId;
  conversationId: ConversationId;

  // Who added this turn
  participant: ParticipantId;
  participantType: 'user' | 'agent' | 'system';

  // When
  timestamp: Timestamp;

  // Threading
  threadId?: ThreadId;            // null = main thread
  inReplyTo?: TurnId;             // Direct response to
  references?: TurnId[];          // Broader context (email-style)

  // The actual content
  content: TurnContent;

  // Who can see this turn
  visibility: TurnVisibility;

  // For mutable turns (e.g., streaming, tool calls)
  status?: 'pending' | 'streaming' | 'complete' | 'failed';
  updatedAt?: Timestamp;

  // Extension metadata
  metadata?: Record<string, unknown>;
}
```

### Turn Content Types

Turn content is a discriminated union covering all interaction types:

```typescript
type TurnContent =
  | UserMessageContent
  | AgentMessageContent
  | AgentThoughtContent
  | ToolCallContent
  | ToolResultContent
  | AgentToAgentContent
  | HandoffContent
  | SystemEventContent
  | SummaryContent;

// User sends a message
interface UserMessageContent {
  type: 'user-message';
  text: string;
  attachments?: Attachment[];
}

// Agent sends a message (to user or generally)
interface AgentMessageContent {
  type: 'agent-message';
  text: string;

  // Is this meant for the user to see? (vs internal coordination)
  toUser: boolean;

  // For streaming responses
  streaming?: boolean;
  complete?: boolean;
}

// Agent's internal reasoning (trajectory)
interface AgentThoughtContent {
  type: 'agent-thought';
  reasoning: string;

  // Optional structured thinking
  steps?: string[];
  conclusion?: string;
  confidence?: number;           // 0-1
}

// Agent calls a tool
interface ToolCallContent {
  type: 'tool-call';
  tool: string;                  // Tool name/identifier
  input: unknown;                // Tool input parameters

  // Execution state
  status: 'pending' | 'running' | 'completed' | 'failed' | 'cancelled';

  // Populated when complete
  resultTurnId?: TurnId;         // Links to the tool-result turn
}

// Tool returns a result
interface ToolResultContent {
  type: 'tool-result';
  toolCallTurnId: TurnId;        // Links back to the tool-call turn

  output: unknown;               // Tool output
  error?: {
    code: string;
    message: string;
    details?: unknown;
  };

  // Execution metadata
  durationMs?: number;
}

// Agent sends message to another agent
interface AgentToAgentContent {
  type: 'a2a-message';
  toAgent: ParticipantId;

  payload: unknown;              // The message content

  // Request/response pattern
  expectsResponse: boolean;
  responseTimeout?: number;      // ms
  responseTurnId?: TurnId;       // Populated when response received
}

// Control transferred to another participant
interface HandoffContent {
  type: 'handoff';
  fromParticipant: ParticipantId;
  toParticipant: ParticipantId;

  // Why the handoff
  reason?: string;

  // Context for the recipient
  context?: string;

  // Where to resume from
  resumeFromTurn?: TurnId;

  // Was it accepted?
  accepted?: boolean;
  acceptedAt?: Timestamp;
}

// System-generated event turn
interface SystemEventContent {
  type: 'system-event';
  event: string;                 // e.g., 'participant.joined', 'timeout', 'error'
  data?: Record<string, unknown>;
}

// Summarization of previous turns
interface SummaryContent {
  type: 'summary';

  // What turns this summary covers
  coversTurns: {
    from: TurnId;
    to: TurnId;
    count: number;
  };

  // The summary text
  summary: string;

  // Extracted key points
  keyPoints?: string[];
  keyDecisions?: string[];
  openQuestions?: string[];

  // How was this generated
  generatedBy: 'system' | 'agent' | 'user';
  generatedAt: Timestamp;
}

interface Attachment {
  type: 'file' | 'image' | 'link' | 'code';
  name?: string;
  mimeType?: string;
  url?: string;                  // For links/hosted files
  content?: string;              // For inline content (base64 or text)
  size?: number;                 // bytes
}
```

### Turn Visibility

```typescript
type TurnVisibility =
  | { type: 'all' }                                    // All conversation participants
  | { type: 'participants'; ids: ParticipantId[] }    // Specific participants only
  | { type: 'role'; roles: ParticipantRole[] }        // By conversation role
  | { type: 'private' };                              // Only the author

// Visibility modifiers
interface TurnVisibilityOptions {
  visibility: TurnVisibility;

  // Hide from history after this duration
  ephemeral?: boolean;
  ephemeralTtlMs?: number;

  // Redact sensitive fields in history
  redactFields?: string[];
}
```

