## Methods

### conv/create

Create a new conversation.

**Request:**
```typescript
interface ConvCreateRequest {
  // Conversation type
  type?: ConversationType;         // Default: 'mixed'

  // Human-readable subject
  subject?: string;

  // Nest under another conversation
  parentConversationId?: ConversationId;
  parentTurnId?: TurnId;

  // Initial participants to invite
  initialParticipants?: Array<{
    id: ParticipantId;
    role?: ParticipantRole;
    permissions?: Partial<ConversationPermissions>;
  }>;

  // Initial turn (optional)
  initialTurn?: {
    content: TurnContent;
    visibility?: TurnVisibility;
  };

  metadata?: Record<string, unknown>;
}
```

**Response:**
```typescript
interface ConvCreateResponse {
  conversation: Conversation;
  participant: ConversationParticipant;  // Creator's participation record
  initialTurn?: Turn;                     // If initialTurn was provided
}
```

### conv/get

Get conversation details.

**Request:**
```typescript
interface ConvGetRequest {
  conversationId: ConversationId;

  include?: {
    participants?: boolean;        // Include participant list
    threads?: boolean;             // Include thread list
    recentTurns?: number;          // Include N most recent turns
    stats?: boolean;               // Include turn counts, etc.
  };
}
```

**Response:**
```typescript
interface ConvGetResponse {
  conversation: Conversation;

  // If requested
  participants?: ConversationParticipant[];
  threads?: Thread[];
  recentTurns?: Turn[];
  stats?: {
    totalTurns: number;
    turnsByType: Record<TurnContent['type'], number>;
    activeParticipants: number;
    threadCount: number;
  };
}
```

